<?php
/**
 * Plugin Name: YG: Plain XML sitemaps (no XSLT) + blog sitemap in robots.txt
 * Description: 1) Stops All in One SEO adding its XSL stylesheet line to sitemap.xml,
 *              the per-type sitemaps and video-sitemap.xml. Chrome is removing XSLT
 *              support and already shows a red warning banner on those pages; search
 *              engines never used the stylesheet. The filter also drops AIOSEO's
 *              "generated by" comment - nothing else.
 *              2) Adds the separate /blog WordPress install's sitemap (Rank Math) to
 *              the main site's robots.txt, which is the only robots.txt crawlers read.
 *              Production domain only.
 * Version:     1.1.0
 * Author:      YES Germany
 */

defined( 'ABSPATH' ) || exit;

add_filter( 'aioseo_sitemap_show_credits', '__return_false' );

add_filter(
	'robots_txt',
	function ( $output ) {
		if ( 'www.yesgermany.com' !== wp_parse_url( home_url(), PHP_URL_HOST ) ) {
			return $output;
		}
		$line = 'Sitemap: https://www.yesgermany.com/blog/sitemap_index.xml';
		if ( false === strpos( (string) $output, $line ) ) {
			$output = rtrim( (string) $output ) . "\n" . $line . "\n";
		}
		return $output;
	},
	PHP_INT_MAX
);
